WITH cleaned AS (SELECT id, order_id, carrier, shipped_date, delivered_date, cost, status, CAST(cost AS INT) AS cost_int, LAST_DAY(delivered_date) AS delivered_date_month_end, COALESCE(carrier, 'DIRECT') AS carrier_clean FROM shipments WHERE order_id IS NOT NULL) SELECT * FROM (SELECT carrier, order_id, status, cost_int FROM cleaned) src PIVOT (AVG(cost_int) AS total FOR status IN ('IN_TRANSIT' AS in_transit, 'LOST' AS lost, 'RETURNED' AS returned));
